import base64, json, os, numpy as np
from PIL import Image
P = 'pack/'
uri = lambda f, m: f'data:{m};base64,' + base64.b64encode(open(P+f, 'rb').read()).decode()
pack = dict(sites=json.load(open(P+'sites.json')), eph=json.load(open(P+'eph.json')), check=json.load(open(P+'check.json')), valid=json.load(open(P+'valid.json')))
html = f"""<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LUNAR EXPLORER · DexLab</title><style>{open('src/app.css').read()}</style></head><body>
<div id="app"><div id="top"></div><div id="rail"></div><div id="mapwrap"><canvas id="map"></canvas><div class="float" id="zoom"><button data-act="zin">+</button><button data-act="zout">−</button><button data-act="zall">⤢</button><button data-act="full" title="خريطة بملء الشاشة · full-screen map">⛶</button><button class="mob" data-act="rail">☰ الطبقات · Layers</button><button class="railopen" data-act="norail">☰</button></div><div class="float" id="tools"></div><div class="float" id="trip" hidden></div><div class="float" id="hint">انقر موقعاً مرقّماً، أو أي نقطة على الخريطة لتحسب أفقها · Click a lettered site, or any point to compute its horizon</div><div class="float" id="legend" hidden></div><div class="float" id="time"></div><div class="float" id="load">… تحميل التضاريس · loading terrain</div></div><div id="split"></div><div id="panel"></div></div>
<div id="dlg" hidden></div><div class="float" id="pres" hidden></div><div id="pop" hidden></div><div id="paper"></div>
<script>const PACK={json.dumps(pack, ensure_ascii=False)};const IMG={{base:"{uri('base160.jpg','image/jpeg')}",L1:"{uri('C1.png','image/png')}",L2:"{uri('C2.png','image/png')}",dem:"{uri('dem.png','image/png')}",inner:"{uri('inner80.jpg','image/jpeg')}",C3:"{uri('C3.png','image/png')}",nsun:"{uri('nsun.png','image/png')}"}};</script><script>{open('src/app.js').read().replace('/*V3*/', open('src/v3.js').read() + open('src/v4.js').read() + open('src/v5.js').read() + open('src/v6.js').read() + open('src/v7.js').read())}</script></body></html>"""
os.makedirs('dist', exist_ok=True); open('dist/LUNAR_EXPLORER_v7.html', 'w').write(html); print(len(html)/1e6, 'MB')
